import{_ as e,c as a,o,al as i}from"./chunks/framework.CT7RwC5a.js";const r="/main/assets/outlook.Du7ZGXUQ.png",n="/main/assets/orientation.CUxloCh4.png",s="/main/assets/pin_definition.Cvv8_HmW.png",l="/main/assets/wiring.BBRrR8Vg.png",d="/main/assets/motor_servo.CVhidRv6.png",c="/main/assets/radio.DFapzdXd.png",p="/main/assets/gps.DyeUNs44.png",h="/main/assets/power.BDX1ilkp.png",u="/main/assets/sdcard.BkPrsz9G.png",_=JSON.parse('{"title":"Accton Godwit G-A1","description":"","frontmatter":{},"headers":[],"relativePath":"en/flight_controller/accton-godwit_ga1.md","filePath":"en/flight_controller/accton-godwit_ga1.md"}'),m={name:"en/flight_controller/accton-godwit_ga1.md"};function g(b,t,f,P,A,w){return o(),a("div",null,t[0]||(t[0]=[i('<h1 id="accton-godwit-g-a1" tabindex="-1">Accton Godwit G-A1 <a class="header-anchor" href="#accton-godwit-g-a1" aria-label="Permalink to &quot;Accton Godwit G-A1&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 does not manufacture this (or any) autopilot. Contact the <a href="https://cubepilot.org/#/home" target="_blank" rel="noreferrer">manufacturer</a> for hardware support or compliance issues.</p></div><p>The G-A1 is a state-of-the-art flight controller developed derived from the <a href="https://github.com/pixhawk/Pixhawk-Standards/blob/master/DS-012%20Pixhawk%20Autopilot%20v6X%20Standard.pdf" target="_blank" rel="noreferrer">Pixhawk Autopilot v6X Standard</a>.</p><p>It includes an STM32H753 double-precision floating-point FMU processor and an STM32F103 IO coprocessor, multiple IMUs with 6-axis inertial sensors, two pressure/temperature sensors, and a geomagnetic sensor. It also has independent buses and power supplies, and is designed for safety and rich expansion capabilities.</p><p>With an integrated 10/100M Ethernet Physical Layer (PHY), the G-A1 can also communicate with a mission computer (airborne computer), high-end surveying and mapping cameras, and other UxV-mounted equipment for high-speed communications, meeting the needs of advanced UxV systems.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Visit <a href="https://www.accton-iot.com/godwit/" target="_blank" rel="noreferrer">Accton-IoT Godwit</a> for more information.</p></div><p><img src="'+r+'" alt="AccGodwitGA1" title="Accton Godwit G-A1"></p><p><img src="'+n+'" alt="AccGodwitGA1 Top View" title="Accton Godwit G-A1 Top View"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This flight controller is <a href="./../flight_controller/autopilot_manufacturer_supported.html">manufacturer supported</a>.</p></div><h2 id="specifications" tabindex="-1">Specifications <a class="header-anchor" href="#specifications" aria-label="Permalink to &quot;Specifications&quot;">​</a></h2><h3 id="processor" tabindex="-1">Processor <a class="header-anchor" href="#processor" aria-label="Permalink to &quot;Processor&quot;">​</a></h3><ul><li>STM32H753IIK (Arm® Cortex®-M7 480MHz)</li><li>STM32F103 (Arm® Cortex®-M3, 72MHz)</li></ul><h3 id="sensors" tabindex="-1">Sensors <a class="header-anchor" href="#sensors" aria-label="Permalink to &quot;Sensors&quot;">​</a></h3><ul><li>Bosch BMI088 (vibration isolated)</li><li>TDK InvenSense ICM-42688-P x 2 (one vibration isolated)</li><li>TDK Barometric Pressure and Temperature Sensor CP-20100 x 2 (one vibration isolated)</li><li>PNI RM3100 Geomagnetic Sensor (vibration isolated)</li></ul><h3 id="power" tabindex="-1">Power <a class="header-anchor" href="#power" aria-label="Permalink to &quot;Power&quot;">​</a></h3><ul><li>4.6V to 5.7V</li></ul><h3 id="external-ports" tabindex="-1">External ports <a class="header-anchor" href="#external-ports" aria-label="Permalink to &quot;External ports&quot;">​</a></h3><ul><li>2 CAN Buses (CAN1 and CAN2)</li><li>3 TELEM Ports (TELEM1, TELEM2 and TELEM3)</li><li>2 GPS Ports (GPS1 with safety switch, LED, buzzer, and GPS2)</li><li>1 PPM IN</li><li>1 SBUS OUT</li><li>2 USB Ports (1 TYPE-C and 1 JST GH1.25)</li><li>1 10/100Base-T Ethernet Port</li><li>1 DSM/SBUS RC</li><li>1 UART 4</li><li>1 AD&amp;IO Port</li><li>2 Debug Ports (1 IO Debug and 1 FMU Debug)</li><li>1 SPI6 Bus</li><li>4 Power Inputs (Power 1, Power 2, Power C1 and Power C2)</li><li>16 PWM Servo Outputs (A1-A8 from FMU and M1-M8 from IO)</li><li>Micro SD Socket (supports SD 4.1 &amp; SDIO 4.0 in two databus modes: 1 bit (default) and 4 bits)</li></ul><h3 id="size-and-dimensions" tabindex="-1">Size and Dimensions <a class="header-anchor" href="#size-and-dimensions" aria-label="Permalink to &quot;Size and Dimensions&quot;">​</a></h3><ul><li>92.2 (L) x 51.2 (W) x 28.3 (H) mm</li><li>77.6g (carrier board with IMU)</li></ul><h2 id="where-to-buy" tabindex="-1">Where to Buy <a class="header-anchor" href="#where-to-buy" aria-label="Permalink to &quot;Where to Buy&quot;">​</a></h2><ul><li><a href="https://www.accton-iot.com/godwit/" target="_blank" rel="noreferrer">Accton-IoT Godwit</a></li><li><a href="./sales@accton-iot.com.html">sales@accton-iot.com</a></li></ul><h2 id="pinout" tabindex="-1">Pinout <a class="header-anchor" href="#pinout" aria-label="Permalink to &quot;Pinout&quot;">​</a></h2><p><img src="'+s+'" alt="G-A1 Pin definition" title="G-A1 Pin definition"></p><h2 id="uart-mapping" tabindex="-1">UART Mapping <a class="header-anchor" href="#uart-mapping" aria-label="Permalink to &quot;UART Mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Serial#</th><th>Protocol</th><th>Port</th><th>Notes</th></tr></thead><tbody><tr><td>SERIAL1</td><td>Telem1</td><td>UART7</td><td>/dev/ttyS6</td></tr><tr><td>SERIAL2</td><td>Telem2</td><td>UART5</td><td>/dev/ttyS4</td></tr><tr><td>SERIAL3</td><td>GPS1</td><td>USART1</td><td>/dev/ttyS0</td></tr><tr><td>SERIAL4</td><td>GPS2</td><td>UART8</td><td>/dev/ttyS7</td></tr><tr><td>SERIAL5</td><td>Telem3</td><td>USART2</td><td>/dev/ttyS1</td></tr><tr><td>SERIAL6</td><td>UART4</td><td>UART4</td><td>/dev/ttyS3</td></tr><tr><td>SERIAL7</td><td>FMU Debug</td><td>USART3</td><td></td></tr><tr><td>SERIAL8</td><td>OTG2</td><td>USB</td><td></td></tr></tbody></table><h2 id="wiring-diagram" tabindex="-1">Wiring Diagram <a class="header-anchor" href="#wiring-diagram" aria-label="Permalink to &quot;Wiring Diagram&quot;">​</a></h2><p><img src="'+l+'" alt="G-A1 Wiring" title="G-A1 Wiring"></p><h2 id="pwm-output" tabindex="-1">PWM Output <a class="header-anchor" href="#pwm-output" aria-label="Permalink to &quot;PWM Output&quot;">​</a></h2><p>PWM M1-M8 (IO Main PWM), A1-A8(FMU PWM). All these 16 support normal PWM output formats. FMU PWM A1-A6 can support DShot and B-Directional DShot. A1-A8(FMU PWM) are grouped as:</p><ul><li>Group 1: A1, A2, A3, A4</li><li>Group 2: A5, A6</li><li>Group 3: A7, A8</li></ul><p>The motor and servo system should be connected to these ports according to the order outlined in the fuselage reference for your carrier.</p><p><img src="'+d+'" alt="G-A1 PWM Motor Servo" title="G-A1 PWM Motor Servo"></p><h2 id="rc-input" tabindex="-1">RC Input <a class="header-anchor" href="#rc-input" aria-label="Permalink to &quot;RC Input&quot;">​</a></h2><p>For DSM/SBUS receivers, connect them to the DSM/SBUS interface which provides dedicated 3.3V and 5V power pins respectively, and check above &quot;Pinout&quot; for detailed pin definition. PPM receivers should be connected to the PPM interface. And other RC systems can be connected via other spare telemetry ports.</p><p><img src="'+c+'" alt="G-A1 Radio" title="G-A1 Radio"></p><h2 id="gps-compass" tabindex="-1">GPS/Compass <a class="header-anchor" href="#gps-compass" aria-label="Permalink to &quot;GPS/Compass&quot;">​</a></h2><p>The Godwit G-A1 has a built-in compass Due to potential interference, the autopilot is usually used with an external I2C compass as part of a GPS/Compass combination.</p><p><img src="'+p+'" alt="G-A1 GPS" title="G-A1 GPS"></p><h2 id="power-connection-and-battery-monitor" tabindex="-1">Power Connection and Battery Monitor <a class="header-anchor" href="#power-connection-and-battery-monitor" aria-label="Permalink to &quot;Power Connection and Battery Monitor&quot;">​</a></h2><p>This universal controller features a CAN PMU module that supports 3 to 14s lithium batteries. To ensure proper connection, attach the module&#39;s 6-pin connector to the flight control Power C1 and/or Power C2 interface.</p><p>This universal controller does not provide power to the servos. To power them, an external BEC must be connected to the positive and negative terminals of any A1–A8 or M1–M8 port.</p><p><img src="'+h+'" alt="G-A1 Power" title="G-A1 Power"></p><h2 id="sd-card" tabindex="-1">SD Card <a class="header-anchor" href="#sd-card" aria-label="Permalink to &quot;SD Card&quot;">​</a></h2><p>The SD card is NOT included in the package, you need to prepare the SD card and insert it into the slot.</p><p><img src="'+u+'" alt="G-A1 SD Card" title="G-A1 SD Card"></p><h2 id="firmware" tabindex="-1">Firmware <a class="header-anchor" href="#firmware" aria-label="Permalink to &quot;Firmware&quot;">​</a></h2><p>The autopilot is compatible with PX4 firmware. And G-A1 can be detected by QGroundControl automatically. Users can also build it with target &quot;accton-godwit_ga1&quot;</p><p>To <a href="./../dev_setup/building_px4.html">build PX4</a> for this target, open up the terminal and enter:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> accton-godwit_ga1</span></span></code></pre></div><h2 id="more-information-and-support" tabindex="-1">More Information and Support <a class="header-anchor" href="#more-information-and-support" aria-label="Permalink to &quot;More Information and Support&quot;">​</a></h2><ul><li><a href="https://www.accton-iot.com/godwit/" target="_blank" rel="noreferrer">Accton-IoT Godwit</a></li><li><a href="./sales@accton-iot.com.html">sales@accton-iot.com</a></li><li><a href="mailto:support@accton-iot.com" target="_blank" rel="noreferrer">support@accton-iot.com</a></li></ul>',52)]))}const M=e(m,[["render",g]]);export{_ as __pageData,M as default};
